UPDATE project_participants
SET
    permission_level = #{participant.permissionLevel}
WHERE
    project_id = #{projectId} AND
    user_id = #{participant.userId};

mapper.select:
WITH RECURSIVE project_hierarchy AS ( -- 검색 조건에 맞는 항목들 가져오기 SELECT id, parent_id AS parentId, project_id AS projectId, type, name, depth, create_at AS createAt FROM project_items WHERE project_id = #{projectId}
AND name LIKE CONCAT('%', #{query}, '%')
AND type = #{type}
AND method = #{method}
UNION ALL
-- 부모 항목 재귀적으로 가져오기 SELECT pi.id, pi.parent_id AS parentId, pi.project_id AS projectId, pi.type, pi.name, pi.depth, pi.create_at AS createAt FROM project_items pi INNER JOIN project_hierarchy ph ON pi.id = ph.parentId ) SELECT DISTINCT * FROM project_hierarchy;

SELECT COALESCE(MAX(item_order), 0) + 1
FROM project_items
WHERE parent_id = #{parentId}

